package at.andrew.squashtap;

import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
import org.junit.Test;import static org.junit.Assert.*;

public class ManualMatchEntryTest {
    private static final LocalDate TODAY=LocalDate.of(2026,11,7);
    private static class TestClock extends Clock{Instant now=Instant.parse("2026-11-07T09:00:00Z");public ZoneId getZone(){return ZoneId.of("Europe/Vienna");}public Clock withZone(ZoneId z){return Clock.fixed(now,z);}public Instant instant(){return now;}}
    private MatchBook book(){return new MatchBook(new MatchState("current",3),new TestClock());}
    private MatchBook fixture(String kind)throws Exception{return MatchBook.decode(new String(Files.readAllBytes(Paths.get("android/test-fixtures/book-v3-"+kind+".txt")),StandardCharsets.UTF_8).trim());}
    @Test public void enteredSetStoresTotalsWithoutInventingARallySequence(){ScoreState s=ScoreState.completedSet(11,7);assertTrue(s.entered());assertEquals("2|11|7",s.encode());assertEquals(18,s.rallies());assertEquals(0,s.winner());assertFalse(s.undo());assertFalse(s.add(1));assertEquals(s.encode(),ScoreState.decode(s.encode()).encode());}
    @Test public void invalidAndUnfinishedSetTotalsAreRejected(){for(int[] s:new int[][]{{11,10},{12,7},{10,7},{-1,11},{5002,5000}})assertThrows(IllegalArgumentException.class,()->ScoreState.completedSet(s[0],s[1]));assertThrows(IllegalArgumentException.class,()->ScoreState.decode("2|11"));assertThrows(IllegalArgumentException.class,()->ScoreState.decode("2|11|7|0"));}
    @Test public void deuceAndMaximumEnteredScoresRoundtrip(){for(int[] s:new int[][]{{12,10},{15,17},{5001,4999}}){ScoreState a=ScoreState.completedSet(s[0],s[1]);ScoreState b=ScoreState.decode(a.encode());assertEquals(s[0],b.blue());assertEquals(s[1],b.red());assertTrue(b.entered());}}
    @Test public void resetRestoresOrdinaryRallyTracking(){ScoreState s=ScoreState.completedSet(7,11);s.reset();assertFalse(s.entered());assertEquals("1|",s.encode());assertTrue(s.add(0));assertTrue(s.undo());}
    @Test public void enteredSetsFollowBestOfThreeAndFiveProgression(){for(int format:new int[]{3,5}){MatchState m=new MatchState("entered",format);for(int i=0;i<format/2+1;i++)assertTrue(m.enterCompletedSet(11,5+i));assertTrue(m.complete());assertEquals(0,m.winner());assertEquals(format/2+1,m.gameCount());assertFalse(m.enterCompletedSet(0,11));assertEquals(m.encode(),MatchState.decode(m.encode()).encode());}}
    @Test public void enteringAfterANormallyWonSetAppendsWithoutReplacingIt(){MatchState m=new MatchState("entered",3);for(int i=0;i<11;i++)m.add(0);String real=m.game().encode();m.enterCompletedSet(5,11);assertEquals(real,m.game(0).encode());assertEquals(2,m.gameCount());assertTrue(m.game(1).entered());assertFalse(m.complete());}
    @Test public void replacingCurrentPartialScoreKeepsEarlierSets(){MatchState m=new MatchState("entered",5);m.enterCompletedSet(11,7);m.nextGame();m.add(0);m.add(1);m.enterCompletedSet(8,11);assertEquals(11,m.game(0).blue());assertEquals(8,m.game(1).blue());assertEquals(11,m.game(1).red());assertEquals(2,m.gameCount());}
    @Test public void undoEnteredSetRemovesItAsAWholeRatherThanPretendingToUndoAPoint(){MatchState m=new MatchState("entered",5);m.enterCompletedSet(11,5);m.enterCompletedSet(8,11);assertTrue(m.undoEnteredSet());assertTrue(m.undo());assertEquals(1,m.gamesWon(0));assertEquals(0,m.game().rallies());assertEquals(2,m.gameCount());}
    @Test public void undoFromAnEmptyNextSetReturnsToTheEnteredSetAndClearsIt(){MatchState m=new MatchState("entered",3);m.enterCompletedSet(11,7);m.nextGame();assertTrue(m.undoEnteredSet());m.undo();assertEquals(1,m.gameCount());assertFalse(m.hasPoints());assertFalse(m.hasEnteredSets());}
    @Test public void liveRallyUndoAfterEnteredSetRemainsAnOrdinaryPointUndo(){MatchState m=new MatchState("entered",3);m.enterCompletedSet(11,7);m.nextGame();m.add(1);assertFalse(m.undoEnteredSet());m.undo();assertEquals(2,m.gameCount());assertEquals(11,m.game(0).blue());assertTrue(m.undoEnteredSet());}
    @Test public void choosingLoserScoreAlwaysMakesAValidFinalScore(){for(int low:new int[]{0,5,9,10,11,20,4999}){int high=ManualMatchEntry.winningScore(low);assertEquals(low<10?11:low+2,high);assertEquals(0,ScoreState.completedSet(high,low).winner());}assertThrows(IllegalArgumentException.class,()->ManualMatchEntry.winningScore(-1));assertThrows(IllegalArgumentException.class,()->ManualMatchEntry.winningScore(5000));}
    @Test public void fullMatchDraftCanChangeFormatWithoutDroppingEnteredScores(){ManualMatchEntry d=new ManualMatchEntry(TODAY);d.setScore(0,11,7);d.setScore(1,11,8);assertTrue(d.complete());d.chooseFormat(5);assertFalse(d.complete());assertEquals(2,d.size());d.setScore(2,11,9);assertTrue(d.complete());assertFalse(d.canChooseFormat(3));assertEquals(5,d.bestOf());}
    @Test public void invalidSetEditingDoesNotPartiallyMutateTheDraft(){ManualMatchEntry d=new ManualMatchEntry(TODAY);d.setScore(0,11,7);d.setScore(1,8,11);d.setScore(2,11,9);assertThrows(IllegalArgumentException.class,()->d.setScore(1,11,8));assertEquals(8,d.points(1,0));assertEquals(11,d.points(1,1));assertEquals(3,d.size());d.removeLast();assertFalse(d.complete());}
    @Test public void unfinishedAndExtraSetDraftsCannotBeSaved(){ManualMatchEntry d=new ManualMatchEntry(TODAY);d.setScore(0,11,7);assertThrows(IllegalArgumentException.class,()->d.result("not-finished"));d.setScore(1,11,8);assertThrows(IllegalArgumentException.class,()->d.setScore(2,11,9));assertEquals(2,d.size());}
    @Test public void datePickersClampLeapDaysAndRejectFutureDates(){assertEquals(LocalDate.of(2025,2,28),ManualMatchEntry.changeDate(LocalDate.of(2024,2,29),2025,2,29));assertEquals(LocalDate.of(2026,4,30),ManualMatchEntry.changeDate(TODAY,2026,4,31));ManualMatchEntry d=new ManualMatchEntry(TODAY);d.date(TODAY.minusDays(2),TODAY);assertThrows(IllegalArgumentException.class,()->d.date(TODAY.plusDays(1),TODAY));assertEquals(TODAY.minusDays(2),d.date());}
    @Test public void wholeMatchHistoryEntryKeepsTheCurrentScoreTimingAndUndo(){MatchBook b=book();b.add(0);b.add(1);String current=b.current().encode();long start=b.currentStartedAt();ManualMatchEntry d=new ManualMatchEntry(TODAY);d.setScore(0,11,7);d.setScore(1,11,9);MatchResult r=b.importResult(d.result("history-entry"));assertEquals(current,b.current().encode());assertEquals(start,b.currentStartedAt());assertEquals(0,r.startedAt);assertEquals(0,r.finishedAt);assertEquals("Not recorded",r.durationText());assertTrue(b.undo());assertEquals(1,b.count());}
    @Test public void manuallyEnteredMatchCsvRoundtripsWithoutAFormatChange(){ManualMatchEntry d=new ManualMatchEntry(TODAY);d.setScore(0,11,7);d.setScore(1,11,8);MatchResult r=d.result("history");String csv=MatchCsv.export(Collections.singletonList(r),new OpponentDirectory());assertTrue(csv.startsWith("\ufeff"+MatchCsv.HEADER+"\r\n\"1\""));MatchResult parsed=MatchCsv.parse(csv).get(0).result;assertEquals(0,parsed.startedAt);assertEquals(0,parsed.finishedAt);assertEquals(7,parsed.points(0,1));}
    @Test public void firstManualSetRecordsTheCurrentStartAndKeepsItWhenLiveScoringContinues(){TestClock c=new TestClock();MatchBook b=new MatchBook(new MatchState("entered",3),c);c.now=c.now.plusSeconds(300);long entered=c.now.toEpochMilli();b.enterCompletedSet(11,7);assertEquals(entered,b.currentStartedAt());assertTrue(b.currentStartedText().contains("07.11.2026 10:05:00"));b=MatchBook.decode(b.encode(),c);b.nextGame();c.now=c.now.plusSeconds(600);for(int i=0;i<11;i++)b.add(0);MatchResult r=b.result("entered");assertEquals(entered,r.startedAt);assertEquals(c.now.toEpochMilli(),r.finishedAt);assertEquals(600000,r.durationMillis());assertEquals("Europe/Vienna",r.zoneId);}
    @Test public void rejectedManualScoresLeaveAnUnsetStartAndBookUntouched(){MatchBook b=book();String before=b.encode();assertThrows(IllegalArgumentException.class,()->b.enterCompletedSet(11,10));assertEquals(before,b.encode());assertEquals(0,b.currentStartedAt());b.enterCompletedSet(11,7);b.enterCompletedSet(11,9);String complete=b.encode();assertFalse(b.enterCompletedSet(11,8));assertEquals(complete,b.encode());}
    @Test public void additionalManualSetsAndUndoKeepAnExistingStartAndItsZone(){TestClock c=new TestClock();MatchBook b=new MatchBook(new MatchState("entered",5),c);b.add(0);long first=b.currentStartedAt();c.now=c.now.plusSeconds(600);b.enterCompletedSet(11,7);assertEquals(first,b.currentStartedAt());b=MatchBook.decode(b.encode(),Clock.fixed(c.now.plusSeconds(600),ZoneId.of("Asia/Tokyo")));b.enterCompletedSet(8,11);assertEquals(first,b.currentStartedAt());assertTrue(b.currentStartedText().contains("07.11.2026 10:00:00"));assertTrue(b.undo());assertTrue(b.undo());assertFalse(b.current().hasPoints());assertEquals(first,b.currentStartedAt());b.enterCompletedSet(11,9);assertEquals(first,b.currentStartedAt());assertEquals(b.encode(),MatchBook.decode(b.encode()).encode());}
    @Test public void v012UnknownStartStaysUnknownUntilAnotherManualSetIsSaved()throws Exception{String old=new String(Files.readAllBytes(Paths.get("android/test-fixtures/book-v4-manual-untimed.txt")),StandardCharsets.UTF_8).trim();TestClock c=new TestClock();c.now=c.now.plusSeconds(1800);MatchBook b=MatchBook.decode(old,c);assertEquals(old,b.encode());assertEquals(0,b.currentStartedAt());assertEquals(1,b.current().gamesWon(0));assertTrue(b.enterCompletedSet(8,11));assertEquals(c.now.toEpochMilli(),b.currentStartedAt());assertEquals(11,b.current().game(0).blue());assertEquals(b.encode(),MatchBook.decode(b.encode()).encode());}
    @Test public void aNewManualMatchGetsItsOwnStartWithoutChangingTheSavedMatch(){TestClock c=new TestClock();MatchBook b=new MatchBook(new MatchState("first",3),c);b.enterCompletedSet(11,7);long first=b.currentStartedAt();c.now=c.now.plusSeconds(600);b.enterCompletedSet(11,9);assertEquals(first,b.result("first").startedAt);assertEquals(0,b.result("first").finishedAt);b.newMatch("second",3);assertEquals(0,b.currentStartedAt());c.now=c.now.plusSeconds(1200);b.enterCompletedSet(7,11);assertEquals(c.now.toEpochMilli(),b.currentStartedAt());assertEquals(first,b.result("first").startedAt);assertEquals(1,b.result("first").number);assertEquals(b.encode(),MatchBook.decode(b.encode()).encode());}
    @Test public void manuallyEnteredFinalSetDoesNotPretendSubmissionWasTheWinningPointTime(){MatchBook b=book();b.add(0);long start=b.currentStartedAt();b.enterCompletedSet(11,7);b.enterCompletedSet(11,9);MatchResult r=b.result("current");assertEquals(start,r.startedAt);assertEquals(0,r.finishedAt);assertEquals("Not recorded",r.durationText());}
    @Test public void deletedCurrentResultCannotBeRevivedByReenteringItsSet(){MatchBook b=book();b.enterCompletedSet(11,7);b.enterCompletedSet(11,9);b.delete("current");b.undo();b.enterCompletedSet(11,8);assertTrue(b.currentDeleted());assertEquals(0,b.count());}
    @Test public void retirementAfterEnteredSetsRetainsTheRealScoresAndOutcome(){MatchBook b=book();b.enterCompletedSet(11,7);b.retire(0);b=MatchBook.decode(b.encode());assertTrue(b.current().retired());assertTrue(b.current().hasEnteredSets());assertEquals(1,b.result("current").winner());assertEquals(1,b.result("current").gamesWon(0));assertTrue(b.undo());assertTrue(b.current().undoEnteredSet());}
    @Test public void v3ActiveAndRetiredFixturesMigrateWithoutLosingCurrentOrHistoricalResults()throws Exception{for(String kind:new String[]{"active","retired"}){MatchBook b=fixture(kind);assertTrue(b.encode().startsWith("B4:"));assertEquals(1,b.current().gamesWon(0));assertEquals(1,b.current().game().red());assertTrue(b.result("v3-past-retired").retired());assertEquals(kind.equals("retired"),b.current().retired());assertEquals(b.encode(),MatchBook.decode(b.encode()).encode());}}
    @Test public void manualFormatsCannotBeSmuggledIntoOlderVersionLabels(){MatchBook b=book();b.enterCompletedSet(11,7);String text=b.encode();assertThrows(IllegalArgumentException.class,()->MatchBook.decode("B3:"+text.substring(3)));assertThrows(IllegalArgumentException.class,()->MatchState.decode(b.current().encode().replaceFirst("M3","M2")));}
}
